```js
  function render() {
    const t = state.trace;
    const closure = t ? A.closureUpTo(t.b, t.steps) : null; // Map id->dist (includes origin dist0)
    const treeEdges = new Set();
    if (t) for (const [id, d] of t.b.dist) { if (d > 0 && d <= t.steps) { const pe = t.b.parent.get(id); if (pe) treeEdges.add(edgeKey(pe)); } }
    const pathEdges = new Set(); let pathNodes = [];
    if (t && state.pathTargetId && closure.has(state.pathTargetId)) {
      const pe = A.pathEdges(t.b, state.pathTargetId, t.dir);
      pe.forEach(e => pathEdges.add(edgeKey(e)));
      pathNodes = A.pathNodes(t.b, state.pathTargetId, t.dir); // ids
    }
    for (const [id, g] of nodeEl) {
      const isSel = id === state.selectedId;
      const inC = closure ? closure.has(id) : false;
      const d = closure ? closure.get(id) : undefined;
      g.classList.toggle('selected', isSel);
      g.classList.toggle('trace', inC && !isSel);
      g.classList.toggle('dim', !!t && !inC);
      g.classList.toggle('path', pathNodes.includes(id));
      const badge = g.querySelector('.dist-badge');
      if (inC && t && (t.steps === Infinity || d <= t.steps) && (d > 0 || true)) { badge.classList.add('show'); badge.querySelector('text').textContent = d === 0 ? '起' : d; }
      else badge.classList.remove('show');
    }
    for (const [key, p] of edgeEl) {
      p.classList.toggle('trace', treeEdges.has(key));
      p.classList.toggle('dim', !!t && !treeEdges.has(key) && !pathEdges.has(key));
      p.classList.toggle('path', pathEdges.has(key));
    }
    renderBreadcrumb(closure);
    renderInspector(closure, pathNodes);
    renderMinimap(closure);
    renderStatus(closure);
  }
