    const b = A.bfs(graph, state.selectedId, dir);
    const max = 0; for (const d of b.dist.values()) max = Math.max(max, d);
    state.trace = { dir, b, steps: 1, max };
    state.pathTargetId = null;
    render();
  }
  function setSteps(k) { if (!state.trace) return; state.trace.steps = Math.max(0, Math.min(k, state.trace.max)); render(); }
