/* ============================================================
   Relational Web Explorer — design tokens & layout
   语义层已冻结（SDIR 0.2）；本文件仅落地视觉语言（decision point: visual_language）
   ============================================================ */
:root {
  --bg: #eef1f6;
  --panel: #ffffff;
  --ink: #17203a;
  --muted: #5b6579;
  --faint: #8b94a8;
  --line: #dfe4ee;
  --accent: #3b5bdb;
  --accent-deep: #1c2f6b;
  --accent-soft: #e7ecfc;
  --danger: #c2255c;

  --t-client: #7048e8;
  --t-gateway: #1971c2;
  --t-service: #0b8a67;
  --t-data: #d9480f;
  --t-middleware: #e8890c;
  --t-external: #c2255c;

  --radius: 8px;
  --shadow: 0 1px 3px rgba(23, 32, 58, .08), 0 4px 14px rgba(23, 32, 58, .06);
  --font: "Segoe UI", "PingFang SC", "Microsoft YaHei", "Noto Sans SC", system-ui, sans-serif;
}

* { box-sizing: border-box; }
html, body { height: 100%; }
body {
  margin: 0;
  font-family: var(--font);
  color: var(--ink);
  background: var(--bg);
  display: grid;
  grid-template-rows: 58px 44px 1fr;
  overflow: hidden;
  font-size: 13px;
}

button { font-family: inherit; }

/* ---------- header ---------- */
#topbar {
  display: flex;
  align-items: center;
  gap: 18px;
  padding: 0 16px;
  background: var(--panel);
  border-bottom: 1px solid var(--line);
  z-index: 30;
}
.brand { display: flex; align-items: center; gap: 10px; min-width: 0; }
.brand-mark {
  width: 34px; height: 34px; border-radius: 9px;
  background: linear-gradient(135deg, var(--accent), #7048e8);
  color: #fff; font-weight: 700; font-size: 13px;
  display: flex; align-items: center; justify-content: center;
  letter-spacing: .5px;
}
.brand-text h1 { font-size: 15px; margin: 0; line-height: 1.2; white-space: nowrap; }
.brand-text .sub { margin: 1px 0 0; font-size: 11.5px; color: var(--muted); white-space: nowrap; }

.search { position: relative; margin-left: auto; width: 300px; }
#search-input {
  width: 100%; height: 32px; padding: 0 12px;
  border: 1px solid var(--line); border-radius: 999px;
  font: inherit; font-size: 12.5px; color: var(--ink);
  background: #f7f9fc;
}
#search-input:focus { outline: 2px solid var(--accent); outline-offset: 1px; background: #fff; }
#search-results {
  position: absolute; top: 36px; left: 0; right: 0;
  margin: 0; padding: 4px; list-style: none;
  background: var(--panel); border: 1px solid var(--line); border-radius: 10px;
  box-shadow: var(--shadow); z-index: 50; max-height: 280px; overflow: auto;
}
#search-results li {
  padding: 6px 10px; border-radius: 6px; cursor: pointer;
  display: flex; align-items: center; gap: 8px; font-size: 12.5px;
}
#search-results li .t-dot { flex: none; }
#search-results li small { color: var(--faint); margin-left: auto; }
#search-results li.active, #search-results li:hover { background: var(--accent-soft); }
#search-results li.none { color: var(--faint); cursor: default; }

.viewtools { display: flex; gap: 6px; }
.viewtools button {
  height: 30px; min-width: 30px; padding: 0 10px;
  border: 1px solid var(--line); border-radius: 7px;
  background: var(--panel); color: var(--ink);
  font-size: 12.5px; cursor: pointer;
}
.viewtools button:hover { border-color: var(--accent); color: var(--accent); }
.viewtools button:focus-visible { outline: 2px solid var(--accent); outline-offset: 1px; }

/* ---------- breadcrumb bar ---------- */
#breadcrumb-bar {
  display: flex; align-items: center; gap: 10px;
  padding: 0 14px;
  background: var(--panel);
  border-bottom: 1px solid var(--line);
  z-index: 20;
